// src/pages/FarmMap.jsx

import { useRef, useState, useEffect, useCallback } from "react";
import C from "../constants/colors";
import S from "../utils/storage";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Input from "../components/ui/Input";
import Btn from "../components/ui/Btn";

const CROP_OPTIONS = [
  "Tomato","Rice","Wheat","Maize","Cotton","Onion","Potato","Brinjal","Okra",
  "Groundnut","Sugarcane","Turmeric","Banana","Mango","Coconut","Ragi","Bajra",
  "Toor Dal","Urad Dal","Moong Dal","Sesame","Green Chilli","Carrot","Cauliflower",
];

const SOIL_TYPES = ["Red","Black","Loamy","Sandy","Clay","Alluvial"];
const FARM_STATUSES = ["Healthy","Disease Alert","Monitor","Harvested","Fallow"];

const TILE_LAYERS = {
  street: {
    url: "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
    attribution: "© OpenStreetMap contributors",
    label: "🗺️ Map",
  },
  satellite: {
    url: "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",
    attribution: "© Esri, Maxar",
    label: "🛰️ Satellite",
  },
};

function FarmMap({ user, t }) {

  const mapRef = useRef(null);
  const mapInstance = useRef(null);
  const tileLayerRef = useRef(null);
  const placePinRef = useRef(null);
  const farmMarkersRef = useRef({});
  const searchTimerRef = useRef(null);

  const [loaded, setLoaded] = useState(false);
  const [farms, setFarms] = useState(() =>
    Array.isArray(user?.farms) ? user.farms : []
  );

  const [tileMode, setTileMode] = useState("street");
  const [addMode, setAddMode] = useState(false);
  const [confirmRemove, setConfirmRemove] = useState(null);

  const [gpsStatus, setGpsStatus] = useState("idle");

  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [searching, setSearching] = useState(false);

  const [pinCoords, setPinCoords] = useState(null);

  const [formFarm, setFormFarm] = useState({
    name: "",
    crop: CROP_OPTIONS[0],
    size: "",
    soilType: "Red",
    status: "Healthy",
  });

  const TX = {
    title: "Farm Map",
    subtitle: "GPS mapping of your farm plots",
    addPlot: "+ Add Farm",
    yourFarms: "My Farm Plots",
    noFarms: "No farms added yet",
    addFirst: "Click '+ Add Farm' to start",
    area: "Area",
    crop: "Crop",
    plotName: "Plot Name",
    loading: "Loading map...",
    saveFarm: "Save Farm",
    cancel: "Cancel",
    acres: "acres",
  };

  // ─────────────────────────────────────────────
  // Load Leaflet
  // ─────────────────────────────────────────────

  useEffect(() => {

    if (document.querySelector("#leaflet-css")) {
      if (window.L) setLoaded(true);
      return;
    }

    const css = document.createElement("link");
    css.id = "leaflet-css";
    css.rel = "stylesheet";
    css.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
    document.head.appendChild(css);

    const script = document.createElement("script");
    script.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";

    script.onload = () => setLoaded(true);

    document.head.appendChild(script);

  }, []);

  // ─────────────────────────────────────────────
  // Initialize Map
  // ─────────────────────────────────────────────

  useEffect(() => {

    if (!loaded || !mapRef.current || mapInstance.current) return;

    const L = window.L;

    const lat = user?.lat || 9.9252;
    const lon = user?.lon || 78.1198;

    const map = L.map(mapRef.current, {
      zoomControl: true,
    }).setView([lat, lon], 14);

    tileLayerRef.current = L.tileLayer(
      TILE_LAYERS.street.url,
      {
        attribution: TILE_LAYERS.street.attribution,
        maxZoom: 21,
      }
    ).addTo(map);

    // User Marker

    const userIcon = L.divIcon({
      html: `
        <div style="
          width:14px;
          height:14px;
          border-radius:50%;
          background:#1a7a3a;
          border:3px solid white;
          box-shadow:0 2px 8px rgba(0,0,0,0.4);
        "></div>
      `,
      iconSize: [20, 20],
      iconAnchor: [10, 10],
    });

    L.marker([lat, lon], { icon: userIcon })
      .addTo(map)
      .bindPopup("📍 Your Location");

    // Existing farms

    farms.forEach(farm => {
      if (farm?.lat && farm?.lon) {
        addMarker(L, map, farm);
      }
    });

    map.on("click", e => {
      if (!addMode) return;
      movePlacePin(L, map, e.latlng.lat, e.latlng.lng);
    });

    mapInstance.current = map;

  }, [loaded]);

  // ─────────────────────────────────────────────
  // Tile Toggle
  // ─────────────────────────────────────────────

  useEffect(() => {

    const map = mapInstance.current;
    const L = window.L;

    if (!map || !L) return;

    if (tileLayerRef.current) {
      tileLayerRef.current.remove();
    }

    const layer = TILE_LAYERS[tileMode];

    tileLayerRef.current = L.tileLayer(layer.url, {
      attribution: layer.attribution,
      maxZoom: 21,
    }).addTo(map);

  }, [tileMode]);

  // ─────────────────────────────────────────────
  // Placement Pin
  // ─────────────────────────────────────────────

  const movePlacePin = useCallback((L, map, lat, lon) => {

    const pinIcon = L.divIcon({
      html: `
        <div style="
          background:#e05c00;
          color:white;
          padding:4px 8px;
          border-radius:6px;
          font-size:11px;
          font-weight:700;
        ">
          📌 Farm Position
        </div>
      `,
      className: "",
    });

    if (placePinRef.current) {
      placePinRef.current.setLatLng([lat, lon]);
    }
    else {

      placePinRef.current = L.marker(
        [lat, lon],
        {
          icon: pinIcon,
          draggable: true,
        }
      ).addTo(map);

      placePinRef.current.on("dragend", e => {

        const pos = e.target.getLatLng();

        setPinCoords({
          lat: pos.lat,
          lon: pos.lng,
        });

      });

    }

    setPinCoords({ lat, lon });

  }, []);

  const removePlacePin = useCallback(() => {

    if (placePinRef.current) {
      placePinRef.current.remove();
      placePinRef.current = null;
    }

    setPinCoords(null);

  }, []);

  // ─────────────────────────────────────────────
  // GPS
  // ─────────────────────────────────────────────

  const handleGPS = () => {

    if (!navigator.geolocation) {
      setGpsStatus("error");
      return;
    }

    setGpsStatus("loading");

    navigator.geolocation.getCurrentPosition(

      pos => {

        const lat = pos.coords.latitude;
        const lon = pos.coords.longitude;

        const map = mapInstance.current;
        const L = window.L;

        map.flyTo([lat, lon], 18);

        movePlacePin(L, map, lat, lon);

        setGpsStatus("done");

        setTimeout(() => {
          setGpsStatus("idle");
        }, 3000);

      },

      () => {
        setGpsStatus("error");
      },

      {
        enableHighAccuracy: true,
      }

    );

  };

  // ─────────────────────────────────────────────
  // Search Location
  // ─────────────────────────────────────────────

  const handleSearch = query => {

    setSearchQuery(query);

    clearTimeout(searchTimerRef.current);

    if (query.length < 3) {
      setSearchResults([]);
      return;
    }

    setSearching(true);

    searchTimerRef.current = setTimeout(async () => {

      try {

        const url =
          `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query + ", India")}&limit=5`;

        const res = await fetch(url);

        const data = await res.json();

        setSearchResults(data);

      }
      catch {
        setSearchResults([]);
      }
      finally {
        setSearching(false);
      }

    }, 500);

  };

  const selectSearchResult = result => {

    const lat = parseFloat(result.lat);
    const lon = parseFloat(result.lon);

    const map = mapInstance.current;
    const L = window.L;

    map.flyTo([lat, lon], 17);

    movePlacePin(L, map, lat, lon);

    setSearchResults([]);

  };

  // ─────────────────────────────────────────────
  // Add Farm Marker
  // ─────────────────────────────────────────────

  const addMarker = (L, map, farm) => {

    const color =
      farm.status === "Healthy"
        ? "#1a7a3a"
        : farm.status === "Disease Alert"
        ? "#b83232"
        : "#c87010";

    const icon = L.divIcon({
      html: `
        <div style="
          background:${color};
          color:white;
          padding:4px 10px;
          border-radius:6px;
          font-size:11px;
          font-weight:700;
          box-shadow:0 2px 8px rgba(0,0,0,0.35);
        ">
          🌾 ${farm.crop}
        </div>
      `,
      className: "",
    });

    const marker = L.marker(
      [farm.lat, farm.lon],
      { icon }
    )
      .addTo(map)
      .bindPopup(`
        <b>${farm.name}</b><br/>
        Crop: ${farm.crop}<br/>
        Area: ${farm.size} acres<br/>
        Soil: ${farm.soilType}<br/>
        Status: ${farm.status}
      `);

    farmMarkersRef.current[farm.id] = marker;

  };

  // ─────────────────────────────────────────────
  // Save Farm
  // ─────────────────────────────────────────────

  const saveFarm = () => {

    if (!formFarm.name) return;

    const farm = {
      id: Date.now(),
      ...formFarm,
      lat: pinCoords?.lat || user?.lat || 9.9252,
      lon: pinCoords?.lon || user?.lon || 78.1198,
    };

    const updated = [...farms, farm];

    setFarms(updated);

    const users = S.get("users") || [];

    const idx = users.findIndex(
      u => u.id === user?.id
    );

    if (idx >= 0) {

      users[idx].farms = updated;

      S.set("users", users);

      S.set("current_user", users[idx]);

    }

    if (window.L && mapInstance.current) {
      addMarker(window.L, mapInstance.current, farm);
    }

    removePlacePin();

    setAddMode(false);

    setFormFarm({
      name: "",
      crop: CROP_OPTIONS[0],
      size: "",
      soilType: "Red",
      status: "Healthy",
    });

  };

  // ─────────────────────────────────────────────
  // Remove Farm
  // ─────────────────────────────────────────────

  const removeFarm = id => {

    const marker = farmMarkersRef.current[id];

    if (marker) {
      marker.remove();
      delete farmMarkersRef.current[id];
    }

    const updated = farms.filter(
      f => f.id !== id
    );

    setFarms(updated);

    const users = S.get("users") || [];

    const idx = users.findIndex(
      u => u.id === user?.id
    );

    if (idx >= 0) {

      users[idx].farms = updated;

      S.set("users", users);

      S.set("current_user", users[idx]);

    }

    setConfirmRemove(null);

  };

  // ─────────────────────────────────────────────
  // UI
  // ─────────────────────────────────────────────

  return (

    <div style={{ padding: 20 }}>

      {/* HEADER */}

      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          marginBottom: 18,
        }}
      >

        <div>

          <h1
            style={{
              margin: 0,
              fontSize: 24,
            }}
          >
            🗺️ {TX.title}
          </h1>

          <p
            style={{
              marginTop: 4,
              color: C.muted,
              fontSize: 13,
            }}
          >
            {TX.subtitle}
          </p>

        </div>

        <div style={{ display: "flex", gap: 8 }}>

          <Btn
            onClick={() =>
              setTileMode(
                tileMode === "street"
                  ? "satellite"
                  : "street"
              )
            }
          >
            {tileMode === "street"
              ? "🛰️ Satellite"
              : "🗺️ Map"}
          </Btn>

          <Btn
            onClick={() => setAddMode(!addMode)}
            variant={addMode ? "amber" : "primary"}
          >
            {addMode ? "📌 Select Location" : TX.addPlot}
          </Btn>

        </div>

      </div>

      {/* ADD FARM PANEL */}

      {addMode && (

        <Card
          style={{
            marginBottom: 14,
            background: "#fff8e1",
          }}
        >

          <div
            style={{
              fontWeight: 700,
              marginBottom: 12,
            }}
          >
            📌 Add Farm Plot
          </div>

          {/* GPS + SEARCH */}

          <div
            style={{
              display: "flex",
              gap: 8,
              marginBottom: 12,
            }}
          >

            <button
              onClick={handleGPS}
              style={{
                border: "none",
                background: "#1a7a3a",
                color: "#fff",
                padding: "10px 16px",
                borderRadius: 8,
                cursor: "pointer",
                fontWeight: 600,
              }}
            >
              {gpsStatus === "loading"
                ? "⏳ Locating..."
                : gpsStatus === "done"
                ? "✅ Located"
                : "📡 Use GPS"}
            </button>

            <div style={{ flex: 1, position: "relative" }}>

              <input
                value={searchQuery}
                onChange={e => handleSearch(e.target.value)}
                placeholder="🔍 Search village or landmark"
                style={{
                  width: "100%",
                  padding: "10px 12px",
                  borderRadius: 8,
                  border: "1px solid #ccc",
                  outline: "none",
                }}
              />

              {searchResults.length > 0 && (

                <div
                  style={{
                    position: "absolute",
                    top: "105%",
                    left: 0,
                    right: 0,
                    background: "#fff",
                    borderRadius: 8,
                    border: "1px solid #ddd",
                    overflow: "hidden",
                    zIndex: 9999,
                  }}
                >

                  {searchResults.map((r, i) => (

                    <div
                      key={i}
                      onClick={() => selectSearchResult(r)}
                      style={{
                        padding: 10,
                        cursor: "pointer",
                        borderBottom: "1px solid #eee",
                        fontSize: 12,
                      }}
                    >
                      📍 {r.display_name}
                    </div>

                  ))}

                </div>

              )}

            </div>

          </div>

          {/* FORM */}

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr 1fr",
              gap: 10,
            }}
          >

            <Input
              label="Plot Name"
              value={formFarm.name}
              onChange={e =>
                setFormFarm({
                  ...formFarm,
                  name: e.target.value,
                })
              }
            />

            <Input
              label="Crop"
              value={formFarm.crop}
              options={CROP_OPTIONS}
              onChange={e =>
                setFormFarm({
                  ...formFarm,
                  crop: e.target.value,
                })
              }
            />

            <Input
              label="Area"
              type="number"
              value={formFarm.size}
              onChange={e =>
                setFormFarm({
                  ...formFarm,
                  size: e.target.value,
                })
              }
            />

            <Input
              label="Soil Type"
              value={formFarm.soilType}
              options={SOIL_TYPES}
              onChange={e =>
                setFormFarm({
                  ...formFarm,
                  soilType: e.target.value,
                })
              }
            />

            <Input
              label="Status"
              value={formFarm.status}
              options={FARM_STATUSES}
              onChange={e =>
                setFormFarm({
                  ...formFarm,
                  status: e.target.value,
                })
              }
            />

          </div>

          <div
            style={{
              display: "flex",
              gap: 8,
              marginTop: 12,
            }}
          >

            <Btn onClick={saveFarm}>
              ✅ Save Farm
            </Btn>

            <Btn
              variant="ghost"
              onClick={() => {
                setAddMode(false);
                removePlacePin();
              }}
            >
              Cancel
            </Btn>

          </div>

        </Card>

      )}

      {/* MAP + SIDEBAR */}

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 320px",
          gap: 14,
        }}
      >

        {/* MAP */}

        <Card
          style={{
            padding: 0,
            overflow: "hidden",
          }}
        >

          {!loaded && (
            <div
              style={{
                height: 500,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              {TX.loading}
            </div>
          )}

          <div
            ref={mapRef}
            style={{
              height: 500,
              display: loaded ? "block" : "none",
            }}
          />

        </Card>

        {/* SIDEBAR */}

        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 10,
          }}
        >

          {/* FARM LIST */}

          <Card style={{ padding: 14 }}>

            <div
              style={{
                fontWeight: 700,
                marginBottom: 12,
              }}
            >
              🌾 {TX.yourFarms} ({farms.length})
            </div>

            {farms.length === 0 && (

              <div
                style={{
                  textAlign: "center",
                  color: "#888",
                  fontSize: 12,
                }}
              >
                {TX.noFarms}
              </div>

            )}

            {farms.map(f => (

              <div
                key={f.id}
                style={{
                  padding: "10px 0",
                  borderBottom: "1px solid #eee",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >

                <div>

                  <div
                    style={{
                      fontWeight: 600,
                      fontSize: 13,
                    }}
                  >
                    {f.name}
                  </div>

                  <div
                    style={{
                      fontSize: 11,
                      color: "#777",
                    }}
                  >
                    {f.crop} · {f.size} acres
                  </div>

                </div>

                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    gap: 6,
                    alignItems: "flex-end",
                  }}
                >

                  <Badge>
                    {f.status}
                  </Badge>

                  {confirmRemove === f.id ? (

                    <div style={{ display: "flex", gap: 4 }}>

                      <button
                        onClick={() => removeFarm(f.id)}
                        style={{
                          border: "none",
                          background: "#b83232",
                          color: "#fff",
                          padding: "4px 8px",
                          borderRadius: 6,
                          cursor: "pointer",
                          fontSize: 11,
                        }}
                      >
                        Confirm
                      </button>

                      <button
                        onClick={() =>
                          setConfirmRemove(null)
                        }
                        style={{
                          border: "1px solid #ccc",
                          background: "#fff",
                          padding: "4px 8px",
                          borderRadius: 6,
                          cursor: "pointer",
                          fontSize: 11,
                        }}
                      >
                        Cancel
                      </button>

                    </div>

                  ) : (

                    <button
                      onClick={() =>
                        setConfirmRemove(f.id)
                      }
                      style={{
                        border: "none",
                        background: "#ffe5e5",
                        color: "#b83232",
                        padding: "5px 10px",
                        borderRadius: 6,
                        cursor: "pointer",
                        fontSize: 11,
                        fontWeight: 700,
                      }}
                    >
                      🗑 Remove
                    </button>

                  )}

                </div>

              </div>

            ))}

          </Card>

        </div>

      </div>

    </div>

  );

}

export default FarmMap;
